// Voiceprint ingestion — fal enrich + three-bucket assembly.
// Input: rows from the Google Sheets node. Output: 3 items, one JSON file each.
// Requires env var FAL_KEY set before starting n8n. See docs/INGEST_PLAN.md.
const FAL_KEY = $env.FAL_KEY || (typeof process !== 'undefined' && process.env.FAL_KEY);
if (!FAL_KEY) throw new Error('FAL_KEY env var not set — export FAL_KEY before starting n8n');

const helpers = this.helpers;
const WIZPER = 'https://fal.run/fal-ai/wizper';
const VISION = 'https://fal.run/openrouter/router/vision';
const VISION_PROMPT = "Describe this social-media image in one sentence for a creator style profile, "
  + "then on a new line prefixed 'TEXT:' transcribe verbatim any text overlaid on the image "
  + "(captions, stickers, titles). If there is no overlaid text, write 'TEXT:'.";
const TOP_QUARTILE = 0.75;

async function fal(url, body) {
  return await helpers.httpRequest({
    method: 'POST', url,
    headers: { Authorization: 'Key ' + FAL_KEY, 'Content-Type': 'application/json' },
    body, json: true,
  });
}

const S = v => (v == null ? '' : String(v)).trim();
const N = v => { const n = parseInt(String(v).replace(/[, ]/g, ''), 10); return isNaN(n) ? 0 : n; };

const rows = $input.all().map(i => i.json);
const corpus = [], visual = [], audience = [];

for (const r of rows) {
  const id = S(r.id) || ('row_' + Math.random().toString(36).slice(2, 10));
  const mtype = S(r.media_type).toLowerCase();
  const author = (S(r.author) || 'creator').toLowerCase();
  const url = S(r.media_url);

  // AUDIENCE bucket — other people's comments never touch the voice corpus
  if (mtype === 'comment' && author === 'audience') {
    audience.push({ id, platform: S(r.platform), text: S(r.caption) || S(r.transcript), likes: N(r.likes) });
    continue;
  }

  let transcript = S(r.transcript) || null;
  let visual_desc = null, overlay = null;
  try {
    if ((mtype === 'video' || mtype === 'audio') && url && !transcript) {
      const res = await fal(WIZPER, { audio_url: url });
      transcript = (res && res.text ? String(res.text).trim() : '') || null;
    }
    if ((mtype === 'image' || mtype === 'story') && url) {
      const res = await fal(VISION, { image_url: url, prompt: VISION_PROMPT });
      const txt = String((res && (res.output || res.text || res.response || res.content)) || '');
      const idx = txt.indexOf('TEXT:');
      if (idx >= 0) { visual_desc = txt.slice(0, idx).trim() || null; overlay = txt.slice(idx + 5).trim() || null; }
      else { visual_desc = txt.trim() || null; }
    }
  } catch (e) {
    console.log('[fal] ' + id + ' (' + mtype + ') failed: ' + e.message + ' — skipping media text');
  }

  // VISUAL bucket — VLM scene description is style, not prose (feeds Stage-5 thumbnails)
  if (visual_desc) visual.push({ id, platform: S(r.platform), visual_desc });

  // VOICE-TEXT bucket — creator's own words only. Overlay text he wrote IS his voice.
  let caption = S(r.caption) || null;
  if (overlay) caption = (caption ? caption + ' ' : '') + overlay;
  const title = S(r.title) || null;
  if (!(transcript || caption || title)) continue;  // pure-image posts feed only visual

  const hook = S(r.hook) || (transcript || caption || '')
    .replace(/\n/g, ' ').split('. ')[0].split(' ').slice(0, 14).join(' ');

  corpus.push({
    id, platform: S(r.platform), title, transcript, caption, hook,
    published_at: S(r.published_at) || null,
    metrics: { views: N(r.views), likes: N(r.likes), comments: N(r.comments) },
    performance_percentile: 0,
  });
}

// engagement-rate percentile within THIS creator's own catalogue (not raw views)
const scored = corpus.map(i => (i.metrics.likes + i.metrics.comments) / Math.max(i.metrics.views, 1));
const sorted = [...scored].sort((a, b) => a - b);
corpus.forEach((it, k) => {
  const rank = sorted.filter(v => v <= scored[k]).length;
  it.performance_percentile = corpus.length ? Math.round((rank / corpus.length) * 1000) / 1000 : 0;
});

const c0 = rows[0] || {};
const corpusDoc = {
  creator: {
    handle: S(c0.creator || c0.handle),
    niche: S(c0.niche),
    platforms: [...new Set(corpus.map(i => i.platform).filter(Boolean))],
  },
  items: corpus,
};

return [
  { json: { fileName: 'corpus.json',           fileContent: JSON.stringify(corpusDoc, null, 2) } },
  { json: { fileName: 'visual_profile.json',   fileContent: JSON.stringify({ items: visual }, null, 2) } },
  { json: { fileName: 'audience_signals.json', fileContent: JSON.stringify({ items: audience }, null, 2) } },
];
